<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Installation — التحضير لمباريات التوظيف</title><style>body{font:16px system-ui;background:#edf4fb;color:#0c3070;margin:0;padding:24px}main{max-width:520px;margin:20px auto;padding:26px;background:white;border-radius:14px}h1{font-size:24px}label{display:block;margin:16px 0 6px}input{box-sizing:border-box;width:100%;padding:12px;border:1px solid #aabed8;border-radius:6px;font:inherit}button{background:#0c3070;color:white;border:0;border-radius:6px;padding:14px 20px;font:inherit;width:100%;margin-top:22px}li{color:#9b3020}p{line-height:1.6}</style></head><body><main><h1>Installer l’administration</h1><p>Cette opération crée les tables MySQL et votre premier compte administrateur. La base et la clé d’application doivent déjà être configurées.</p>@if($errors->any())<ul>@foreach($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul>@endif<form method="post" action="{{ url('/installation') }}">@csrf<label for="token">Jeton d’installation</label><input id="token" name="token" type="password" required autocomplete="off"><label for="name">Nom</label><input id="name" name="name" required value="{{ old('name') }}" autocomplete="name"><label for="email">Adresse e-mail</label><input id="email" name="email" type="email" required value="{{ old('email') }}" autocomplete="email"><label for="password">Mot de passe (12 caractères minimum)</label><input id="password" name="password" type="password" required minlength="12" autocomplete="new-password"><label for="confirm">Confirmer le mot de passe</label><input id="confirm" name="password_confirmation" type="password" required autocomplete="new-password"><button>Créer les tables et mon compte administrateur</button></form></main><script>const setupToken=new URLSearchParams(location.hash.slice(1)).get('token');if(setupToken&&/^[a-f0-9]{64}$/.test(setupToken)){document.getElementById('token').value=setupToken;history.replaceState(null,'',location.pathname);}</script></body></html>

